  autoIssueEvents(
    where: { projectId: $projectId, chainId: $chainId, version: 6 }
    orderBy: "timestamp"
    orderDirection: "desc"
    limit: $limit
    offset: $offset
  ) {
    items { timestamp txHash caller beneficiary stageId count }
    totalCount
  }
}

